    sovereign_forgeashgatevalve_palace = { name = "Suverena forgeashgatevalve palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
ForgeAshGateValveMaker.ironStock=16; ForgeAshGateValveMaker.bronzeStock=12; ForgeAshGateValveMaker.woodStock=12; ForgeAshGateValveMaker.leatherStock=8; ForgeAshGateValveMaker.silverStock=8; ForgeAshGateValveMaker.goldStock=6; ForgeAshGateValveMaker.jewelStock=4; ForgeAshGateValveMaker.pearlStock=4
ForgeAshGateValveMaker.productStock = {}; ForgeAshGateValveMaker.buildings = {}; ForgeAshGateValveMaker.maker = nil; ForgeAshGateValveMaker.activeMaking = {}; ForgeAshGateValveMaker.totalProducts = 0; ForgeAshGateValveMaker.dayTimer = 0
function ForgeAshGateValveMaker.init() ForgeAshGateValveMaker.ironStock=16; ForgeAshGateValveMaker.bronzeStock=12; ForgeAshGateValveMaker.woodStock=12; ForgeAshGateValveMaker.leatherStock=8; ForgeAshGateValveMaker.silverStock=8; ForgeAshGateValveMaker.goldStock=6; ForgeAshGateValveMaker.jewelStock=4; ForgeAshGateValveMaker.pearlStock=4; ForgeAshGateValveMaker.productStock={}; ForgeAshGateValveMaker.buildings={}; ForgeAshGateValveMaker.maker=nil; ForgeAshGateValveMaker.activeMaking={}; ForgeAshGateValveMaker.totalProducts=0; ForgeAshGateValveMaker.dayTimer=0; print("[ForgeAshGateValveMaker] Royal Forge Ash Gate Valve Maker System initialized (6 products, 4 buildings)") end
function ForgeAshGateValveMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ForgeAshGateValveMaker.maker={name=n or ("Zaklopkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zaklopkar najet: %s (spretnost: %d)",ForgeAshGateValveMaker.maker.name,s),"success") end; return true end
function ForgeAshGateValveMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ForgeAshGateValveMaker.build(id) local ok,e=ForgeAshGateValveMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ForgeAshGateValveMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ForgeAshGateValveMaker.getQualityBonus() local b=0; for _,bd in ipairs(ForgeAshGateValveMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ForgeAshGateValveMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ForgeAshGateValveMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ForgeAshGateValveMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ForgeAshGateValveMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ForgeAshGateValveMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ForgeAshGateValveMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ForgeAshGateValveMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ForgeAshGateValveMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ForgeAshGateValveMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ForgeAshGateValveMaker.buildings==0 then return false,"Potrebna zaklopna delavnica" end; if not ForgeAshGateValveMaker.maker then return false,"Potreben zaklopkar" end; return true end
function ForgeAshGateValveMaker.make(pt,qty) qty=qty or 1; local ok,e=ForgeAshGateValveMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ForgeAshGateValveMaker.ironStock=ForgeAshGateValveMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ForgeAshGateValveMaker.bronzeStock=ForgeAshGateValveMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ForgeAshGateValveMaker.woodStock=ForgeAshGateValveMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ForgeAshGateValveMaker.leatherStock=ForgeAshGateValveMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ForgeAshGateValveMaker.silverStock=ForgeAshGateValveMaker.silverStock-d.silverCost*qty end; if d.goldCost then ForgeAshGateValveMaker.goldStock=ForgeAshGateValveMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ForgeAshGateValveMaker.jewelStock=ForgeAshGateValveMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ForgeAshGateValveMaker.pearlStock=ForgeAshGateValveMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ForgeAshGateValveMaker.maker then t=math.max(1,t-math.floor(ForgeAshGateValveMaker.maker.skill/13)) end; table.insert(ForgeAshGateValveMaker.activeMaking,{id="forgeashgatevalve_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ForgeAshGateValveMaker.completeMaking(m) local q=1.0+(ForgeAshGateValveMaker.getQualityBonus()/100); if ForgeAshGateValveMaker.maker then q=q+(ForgeAshGateValveMaker.maker.skill/140) end; q=math.min(2.5,q); ForgeAshGateValveMaker.productStock[m.productType]=(ForgeAshGateValveMaker.productStock[m.productType] or 0)+m.quantity; ForgeAshGateValveMaker.totalProducts=ForgeAshGateValveMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ForgeAshGateValveMaker.maker then ForgeAshGateValveMaker.maker.itemsMade=ForgeAshGateValveMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ForgeAshGateValveMaker.maker.skill=math.min(100,ForgeAshGateValveMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zaklopka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"forgeashgatevalve.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ForgeAshGateValveMaker.update(dt) if not _G.state then return end; ForgeAshGateValveMaker.dayTimer=ForgeAshGateValveMaker.dayTimer+dt; if ForgeAshGateValveMaker.dayTimer>=30 then ForgeAshGateValveMaker.dayTimer=0; for i=#ForgeAshGateValveMaker.activeMaking,1,-1 do local m=ForgeAshGateValveMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ForgeAshGateValveMaker.completeMaking(m); table.remove(ForgeAshGateValveMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ForgeAshGateValveMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ForgeAshGateValveMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ForgeAshGateValveMaker.getStats() return {ironStock=ForgeAshGateValveMaker.ironStock,bronzeStock=ForgeAshGateValveMaker.bronzeStock,woodStock=ForgeAshGateValveMaker.woodStock,leatherStock=ForgeAshGateValveMaker.leatherStock,silverStock=ForgeAshGateValveMaker.silverStock,goldStock=ForgeAshGateValveMaker.goldStock,jewelStock=ForgeAshGateValveMaker.jewelStock,pearlStock=ForgeAshGateValveMaker.pearlStock,productStock=ForgeAshGateValveMaker.productStock,numBuildings=#ForgeAshGateValveMaker.buildings,hasMaker=ForgeAshGateValveMaker.maker~=nil,makerName=ForgeAshGateValveMaker.maker and ForgeAshGateValveMaker.maker.name or "—",makerSkill=ForgeAshGateValveMaker.maker and ForgeAshGateValveMaker.maker.skill or 0,activeMaking=#ForgeAshGateValveMaker.activeMaking,totalProducts=ForgeAshGateValveMaker.totalProducts} end
